fn pick(args: &[String]) -> Result<&str, &'static str> {
    if args.len() < 2 {
        return Err("missing");
    }
    Ok(&args[1])
}

fn main() {
    let a = vec![String::from("prog")];
    let b = vec![String::from("prog"), String::from("rust")];
    println!("{:?} {:?}", pick(&a), pick(&b));
}

fn main() {
    let line = "I love RUST";
    let q = "rust";
    println!("{} {}", line.contains(q), line.to_lowercase().contains(q));
}

fn longest_line<'a>(text: &'a str) -> &'a str {
    text.lines().max_by_key(|l| l.len()).unwrap_or("")
}

fn main() {
    let t = "ab\nabcd\nabc\nwxyz";
    println!("{}", longest_line(t));
}
